import React from 'react';

const Home = () => {
  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '40px 20px' }}>
      <div style={{ textAlign: 'center', marginBottom: '60px' }}>
        <h1 style={{
          color: 'var(--primary-maroon)',
          fontSize: '48px',
          marginBottom: '20px',
          animation: 'fadeInUp 0.6s ease',
        }}>
          Welcome to NextGen
        </h1>

      </div>




    </div>
  );
};

export default Home;
